<template><el-card><template #header>剪刀售后工单</template><el-form inline><el-form-item label="工单/SN"><el-input v-model="query.keyword" placeholder="工单号或SN码" clearable/></el-form-item><el-form-item label="类型"><el-select v-model="query.serviceType" clearable><el-option label="维修" value="repair"/><el-option label="置换" value="replacement"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option v-for="x in statuses" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form><el-table :data="rows" v-loading="loading" border><el-table-column prop="request_no" label="工单号"/><el-table-column prop="sn" label="SN码"/><el-table-column label="类型"><template #default="{row}">{{row.service_type==='repair'?'维修':'置换'}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="issue_description" label="问题描述"/><el-table-column prop="seller_message" label="商家留言"/><el-table-column prop="created_at" label="申请时间"/></el-table></el-card></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {fetchScissorsAfterSales,type ScissorsAfterSaleRow} from '../../api/admin';const query=reactive({keyword:'',serviceType:'',status:''});const rows=ref<ScissorsAfterSaleRow[]>([]);const loading=ref(false);const statuses=[{value:'submitted',label:'待审核'},{value:'awaiting_shipment',label:'待寄回'},{value:'shipped',label:'已寄回'},{value:'inspecting',label:'检测中'},{value:'repairing',label:'维修中'},{value:'returning',label:'返件中'},{value:'completed',label:'已完成'},{value:'rejected',label:'已拒绝'}];const load=async()=>{loading.value=true;try{rows.value=await fetchScissorsAfterSales(query)}catch(e){ElMessage.error(e instanceof Error?e.message:'查询失败')}finally{loading.value=false}};const reset=()=>{Object.assign(query,{keyword:'',serviceType:'',status:''});load()};onMounted(load);</script>
